import React, { useMemo } from "react";
import { 
  AbsoluteFill, 
  useCurrentFrame, 
  useVideoConfig, 
  spring, 
  interpolate, 
  Easing 
} from '../remotionShim';
import { getPointAtLength, getLength, evolvePath } from "@remotion/paths";

{/* Start Google Fonts Loader */}
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]); 

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700;800`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */}



export type SnakeJourneyProps = Record<string, any>;

const SnakeJourney: React.FC<SnakeJourneyProps> = ({
  backgroundColor = "#0F172A",
  transparentBackground = false,
  durationInSeconds = 12,
  pathColor = "#334155",
  activePathColor = "#3B82F6",
  pathWidth = 8,
  travelerColor = "#FFFFFF",
  travelerSize = 24,
  phases = [
    { title: "Discovery Phase", description: "Mapping out the requirements and initial strategy.", color: "#3B82F6" },
    { title: "Execution Phase", description: "Building the core structure and implementing features.", color: "#10B981" },
    { title: "Delivery Phase", description: "Final testing and handing over the completed project.", color: "#8B5CF6" }
  ],
}) => {
  useFontLoader(["Inter"]);

  const frame = useCurrentFrame();
  const { fps, width, height, durationInFrames } = useVideoConfig();

  const bgColor = transparentBackground ? "transparent" : backgroundColor;

  // Dynamic Path Generation based on number of phases
  const numPhases = Math.max(1, phases.length);
  const startY = height * 0.85;
  const endY = height * 0.15;
  const totalYDistance = startY - endY;
  const segmentHeight = totalYDistance / numPhases;

  const pathString = useMemo(() => {
    let segments = `M ${width * 0.5} ${startY}`;
    for (let i = 0; i < numPhases; i++) {
      const isRight = i % 2 === 0;
      const segStartY = startY - i * segmentHeight;
      const segEndY = startY - (i + 1) * segmentHeight;
      const c1x = isRight ? width * 0.9 : width * 0.1;
      const c2x = isRight ? width * 0.9 : width * 0.1;
      segments += ` C ${c1x} ${segStartY}, ${c2x} ${segEndY}, ${width * 0.5} ${segEndY}`;
    }
    return segments;
  }, [width, startY, segmentHeight, numPhases]);

  const pathLength = useMemo(() => getLength(pathString), [pathString]);

  // Dynamic Timing Calculations
  const totalActiveFrames = durationInFrames * 0.85;
  const perPhaseFrames = totalActiveFrames / numPhases;
  const moveDuration = perPhaseFrames * 0.75;
  const pauseDuration = perPhaseFrames * 0.25;

  const moves = useMemo(() => {
    const computedMoves = [];
    let currentStart = fps * 0.5; // Initial delay
    for (let i = 0; i < numPhases; i++) {
      computedMoves.push({
        start: currentStart,
        end: currentStart + moveDuration
      });
      currentStart += moveDuration + pauseDuration;
    }
    return computedMoves;
  }, [fps, moveDuration, pauseDuration, numPhases]);

  // Calculate Progress
  let totalProgress = 0;
  moves.forEach((m) => {
    totalProgress += interpolate(
      frame,
      [m.start, m.end],
      [0, 1],
      { extrapolateLeft: 'clamp', extrapolateRight: 'clamp', easing: Easing.inOut(Easing.cubic) }
    );
  });
  
  const progress = totalProgress / numPhases;
  const clampedProgress = Math.max(0, Math.min(1, progress));

  // Path Evolutions
  const activePathEvolve = evolvePath(clampedProgress, pathString);
  
  // Safe point sampling to avoid floating point bounds errors
  const safePointLength = Math.max(0.001, Math.min(pathLength * 0.9999, pathLength * clampedProgress));
  const travelingNodePoint = getPointAtLength(pathString, safePointLength);

  // Traveler scale intro
  const travelerScale = spring({ frame: frame - 10, fps, config: { damping: 12 } });
  const safeTravelerScale = Math.max(0, travelerScale);

  const startPt = { x: width * 0.5, y: startY };

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, fontFamily: "Inter", transition: "none" }}>
      <svg width="100%" height="100%" viewBox={`0 0 ${width} ${height}`} style={{ overflow: "visible" }}>
        
        {/* Background Faint Path */}
        <path 
          d={pathString} 
          stroke={pathColor} 
          strokeWidth={pathWidth} 
          fill="none" 
          opacity={0.3}
          strokeLinecap="round"
          style={{ transition: "none" }}
        />
        
        {/* Active Highlighted Path */}
        <path 
          d={pathString} 
          stroke={activePathColor} 
          strokeWidth={pathWidth} 
          fill="none" 
          strokeDasharray={activePathEvolve.strokeDasharray}
          strokeDashoffset={activePathEvolve.strokeDashoffset}
          strokeLinecap="round"
          style={{ transition: "none" }}
        />

        {/* Start Dot */}
        <circle cx={startPt.x} cy={startPt.y} r={pathWidth} fill={pathColor} />

        {/* Phases Map */}
        {phases.slice(0, numPhases).map((phase, i) => {
          const ratio = (i + 1) / numPhases;
          const pointLength = Math.max(0, Math.min(pathLength * 0.9999, pathLength * ratio));
          const pt = getPointAtLength(pathString, pointLength);
          
          const trigger = Math.max(0, moves[i].end - 15);
          const scale = spring({ frame: Math.max(0, frame - trigger), fps, config: { damping: 12 } });
          const safeScale = Math.max(0, scale);
          
          const lineLength = 60;
          const lineDash = interpolate(frame, [trigger, trigger + 15], [0, lineLength], { extrapolateLeft: 'clamp', extrapolateRight: 'clamp' });
          const textOpacity = interpolate(frame, [trigger + 10, trigger + 25], [0, 1], { extrapolateLeft: 'clamp', extrapolateRight: 'clamp' });
          
          const dir = i % 2 === 0 ? -1 : 1;
          const textTranslateX = interpolate(frame, [trigger + 10, trigger + 25], [dir * -20, 0], { extrapolateLeft: 'clamp', extrapolateRight: 'clamp', easing: Easing.out(Easing.quad) });

          const boxWidth = 440;
          const boxHeight = 180;
          const xPos = dir === -1 ? pt.x - lineLength - boxWidth : pt.x + lineLength;
          const yPos = pt.y - boxHeight / 2;

          return (
            <g key={i} style={{ transition: "none" }}>
              {/* Connection Line */}
              <line 
                x1={pt.x} 
                y1={pt.y} 
                x2={pt.x + dir * lineLength} 
                y2={pt.y} 
                stroke={phase.color} 
                strokeWidth={3}
                strokeDasharray={lineLength}
                strokeDashoffset={lineLength - lineDash}
                style={{ transition: "none" }}
              />
              
              {/* Text Container */}
              <foreignObject 
                x={xPos} 
                y={yPos} 
                width={boxWidth} 
                height={boxHeight}
                style={{ opacity: textOpacity, transition: 'none', overflow: 'visible' }}
              >
                <div style={{ 
                  display: 'flex', 
                  flexDirection: 'column', 
                  alignItems: dir === -1 ? 'flex-end' : 'flex-start', 
                  textAlign: dir === -1 ? 'right' : 'left',
                  width: '100%',
                  height: '100%',
                  justifyContent: 'center',
                  transform: `translateX(${textTranslateX}px)`,
                  transition: 'none'
                }}>
                  <div style={{ color: phase.color, fontSize: '40px', fontWeight: 800, textTransform: 'uppercase', letterSpacing: '2px', marginBottom: '8px' }}>
                    {phase.title}
                  </div>
                  <div style={{ color: '#E2E8F0', fontSize: '26px', lineHeight: 1.4 }}>
                    {phase.description}
                  </div>
                </div>
              </foreignObject>
              
              {/* Phase Node Circle */}
              <g style={{ transform: `translate(${pt.x}px, ${pt.y}px) scale(${safeScale})`, transition: "none" }}>
                <circle cx={0} cy={0} r={16} fill={phase.color} />
                <circle cx={0} cy={0} r={26} fill="none" stroke={phase.color} strokeWidth={2} opacity={0.6} />
              </g>
            </g>
          );
        })}

        {/* Traveling Node */}
        <g style={{ 
          transform: `translate(${travelingNodePoint.x}px, ${travelingNodePoint.y}px) scale(${safeTravelerScale})`,
          transition: "none"
        }}>
          <circle 
            cx={0} 
            cy={0} 
            r={travelerSize / 2} 
            fill={travelerColor} 
            style={{ filter: `drop-shadow(0px 0px 16px ${activePathColor})`, transition: "none" }}
          />
        </g>
      </svg>
    </AbsoluteFill>
  );
};

export default SnakeJourney;